# Apply extensions to TRANSLATIONS
for _l_code, _entries in _DASHBOARD_LABEL_EXTENSIONS.items():
    if _l_code in TRANSLATIONS:
        TRANSLATIONS[_l_code].update(_entries)

# Ensure fallback parity across all 14 languages for any missing keys
for _l_code in SUPPORTED_LANGUAGES:
    if _l_code in TRANSLATIONS:
        for _ek, _ev in _DASHBOARD_LABEL_EXTENSIONS["en"].items():
            if _ek not in TRANSLATIONS[_l_code]:
                _canon = METRIC_HEADING_ALIASES.get(_ek)
                if _canon and _canon in TRANSLATIONS[_l_code]:
                    TRANSLATIONS[_l_code][_ek] = TRANSLATIONS[_l_code][_canon]
                else:
                    TRANSLATIONS[_l_code][_ek] = _ev


def t(key: str, lang: Optional[str] = None, default: Optional[str] = None) -> str:
    """
    Translates a translation key into the active or requested language.
    Falls back gracefully to English if the key is missing in the chosen language.
    Never crashes on missing keys or unmapped languages.
    Prevents raw internal keys (such as lbl_* prefixes) from leaking to the UI.
    """
    if lang is None:
        try:
            lang = st.session_state.get("language", "en")
        except Exception:
            lang = "en"

    lang_dict = TRANSLATIONS.get(lang, TRANSLATIONS.get("en", {}))
    en_dict = TRANSLATIONS.get("en", {})

    # 1. Direct dictionary match
    if key in lang_dict:
        return lang_dict[key]

    # 2. Check alias mapping (e.g., lbl_total_area -> lbl_farm_size)
    canonical_key = METRIC_HEADING_ALIASES.get(key)
    if canonical_key:
        if canonical_key in lang_dict:
            return lang_dict[canonical_key]
        if canonical_key in en_dict:
            return en_dict[canonical_key]

    # 3. Graceful fallback to English dictionary
    if key in en_dict:
        return en_dict[key]

    # 4. Explicit user/caller provided default
    if default is not None:
        return default

    # 5. Known dashboard/welcome fallbacks
    if key in DASHBOARD_HEADING_DEFAULTS:
        return DASHBOARD_HEADING_DEFAULTS[key]
    if canonical_key and canonical_key in DASHBOARD_HEADING_DEFAULTS:
        return DASHBOARD_HEADING_DEFAULTS[canonical_key]

    if key == "dash_plan_preview":
        return lang_dict.get("dash_plan_summary", en_dict.get("dash_plan_summary", "Chronological morning, afternoon, and evening tasks synthesized for current conditions."))
    if key == "dash_rec_preview":
        return lang_dict.get("dash_crop_rec_summary", en_dict.get("dash_crop_rec_summary", "Evaluate crop suitability from soil nutrients, or inspect disease & pest risks."))

    # 6. Sanitize any internal keys containing "lbl" so no internal key leaks to the UI
    if "lbl" in key:
        clean = key
        if clean.startswith("lbl_"):
            clean = clean[4:]
        elif clean.endswith("_lbl"):
            clean = clean[:-4]
        clean = clean.replace("lbl", "").replace("_", " ").strip().title()
        return clean or key

    return key


def get_translation_coverage_report() -> Dict[str, Any]:
    """
    Generates an automated, transparent translation coverage report.
    Audits missing keys for every supported language against the master English catalog.
    """
    en_keys = set(TRANSLATIONS.get("en", {}).keys())
    total_keys = len(en_keys)
    summary = {}
    complete_langs = []
    partial_langs = []

    for code, name in SUPPORTED_LANGUAGES.items():
        lang_dict = TRANSLATIONS.get(code, {})
        translated_keys = set(lang_dict.keys())
        matching = translated_keys.intersection(en_keys)
        missing = sorted(list(en_keys - matching))
        count = len(matching)
        pct = round((count / total_keys * 100), 1) if total_keys > 0 else 0.0
        is_complete = (len(missing) == 0)
        if is_complete:
            complete_langs.append(code)
        else:
            partial_langs.append(code)

        summary[code] = {
            "name": name,
            "total_keys": total_keys,
            "translated_keys": count,
            "missing_keys": missing,
            "coverage_pct": pct,
            "status": "Complete (100%)" if is_complete else f"Partial ({pct}%)"
        }

    details = [
        {
            "Language Code": code,
            "Language Name": info["name"],
            "Translated Keys": info["translated_keys"],
            "Total Keys": info["total_keys"],
            "Coverage (%)": f"{info['coverage_pct']}%",
            "Status": info["status"]
        }
        for code, info in summary.items()
    ]

    return {
        "total_keys": total_keys,
        "master_total_keys": total_keys,
        "total_languages": len(SUPPORTED_LANGUAGES),
        "complete_languages": complete_langs,
        "partial_languages": partial_langs,
        "coverage_summary": summary,
        "details": details
    }

